import React, { useState, useEffect } from 'react';
import upArrow from "../../img/up-arrow.svg";
import "./toTop.css";

const ToTop = () => {
    const [bottomOffset, setBottomOffset] = useState(20);

    const scrollToTop = () =>
        window.scrollTo({ top: 0, behavior: 'smooth' });

    useEffect(() => {
        const footer = document.querySelector('footer');
        if (!footer) return;

        const onScroll = () => {
            const rect = footer.getBoundingClientRect();
            if (rect.top < window.innerHeight) {
                // footer encroaching viewport → lift the button
                setBottomOffset(window.innerHeight - rect.top + 20);
            } else {
                // normal position
                setBottomOffset(20);
            }
        };

        window.addEventListener('scroll', onScroll, { passive: true });
        onScroll(); // initialize immediately
        return () => window.removeEventListener('scroll', onScroll);
    }, []);

    return (
        <aside
            className="toTop"
            style={{ bottom: `${bottomOffset}px` }}
            onClick={scrollToTop}
        >
            <div className="toTop-container">
                <img src={upArrow} alt="Up arrow" className="toTop-img" />
            </div>
        </aside>
    );
};

export default ToTop;
